  return style === '|' ? applyLiteralChomping(lines, chomping) : applyFoldedChomping(lines, chomping);
}

function detectBlockIndent(state, parentIndent) {
  for (let i = state.index; i < state.lines.length; i += 1) {
    const line = state.lines[i];
    if (isBlankLine(line)) {
      continue;
    }
    const indent = countIndent(line);
    if (indent > parentIndent) {
      return indent;
    }
    break;
  }
  return parentIndent + 1;
}

function applyLiteralChomping(lines, chomping) {
  if (lines.length === 0) {
    return '';
  }

  const { contentLines, trailingBlanks } = splitTrailingBlankLines(lines);
  const core = contentLines.join('\n');
  if (chomping === '-') {
    return core;
  }
  if (chomping === '+') {
    return `${core}${'\n'.repeat(trailingBlanks + 1)}`;
  }
  return `${core}\n`;
}

function applyFoldedChomping(lines, chomping) {
  if (lines.length === 0) {
    return '';
  }

  const { contentLines, trailingBlanks } = splitTrailingBlankLines(lines);
  let core = '';

  for (let i = 0; i < contentLines.length; i += 1) {
    const line = contentLines[i];
    if (i === 0) {
      core += line;
      continue;
    }

    const previous = contentLines[i - 1];
    if (previous === '' || line === '') {
      core += '\n';
    } else {
      core += ' ';
    }
    core += line;
  }

  if (chomping === '-') {
    return core;
  }
  if (chomping === '+') {
    return `${core}${'\n'.repeat(trailingBlanks + 1)}`;
  }
  return `${core}\n`;
}

function splitTrailingBlankLines(lines) {
  let end = lines.length;
  while (end > 0 && lines[end - 1] === '') {
    end -= 1;
  }
  return {
    contentLines: lines.slice(0, end),
    trailingBlanks: lines.length - end,
  };
}

function isBlockScalarHeader(text) {
  if (text.length === 0) {
    return false;
  }
  if (text[0] !== '|' && text[0] !== '>') {
    return false;
  }
  for (let i = 1; i < text.length; i += 1) {
    const ch = text[i];
    if (ch !== '+' && ch !== '-' && !isDigit(ch)) {
      return false;
    }
  }
  return true;
}

function peekSignificant(state) {
  let index = state.index;
  while (index < state.lines.length) {
    const line = state.lines[index];
    if (isBlankLine(line)) {
      index += 1;
      continue;
    }
    const indent = countIndent(line);
    const content = trimComment(line.slice(indent));
    if (content.length === 0) {
      index += 1;
      continue;
    }
    return { index, indent, content };
  }
  return null;
}

function skipIgnorable(state) {
  while (true) {
    const next = peekSignificant(state);
    if (next === null || next.index === state.index) {
      return;
    }
    state.index = next.index;
    return;
  }
}

