import { YamlFloat, YamlInteger, YamlTimestamp, isScalarWrapper, scalarText } from './model.mjs';
import { isDigit, isHexDigit } from './text.mjs';

const BOOLEAN_VALUES = new Map([
  ['y', true],
  ['yes', true],
  ['n', false],
  ['no', false],
  ['true', true],
  ['false', false],
  ['on', true],
  ['off', false],
]);

const NULL_VALUES = new Set(['', '~', 'null']);

export function parseSingleQuoted(text) {
  let result = '';
  for (let i = 1; i < text.length - 1; i += 1) {
    const ch = text[i];
    if (ch === "'" && i + 1 < text.length - 1 && text[i + 1] === "'") {
      result += "'";
      i += 1;
    } else {
      result += ch;
    }
  }
  return result;
}

export function parseDoubleQuoted(text) {
  let result = '';
  for (let i = 1; i < text.length - 1; i += 1) {
    const ch = text[i];
    if (ch !== '\\') {
      result += ch;
      continue;
    }

    if (i + 1 >= text.length - 1) {
      break;
    }

    const escaped = text[i + 1];
    i += 1;

    if (escaped === '0') {
      result += '\0';
    } else if (escaped === 'a') {
      result += '\x07';
    } else if (escaped === 'b') {
      result += '\b';
    } else if (escaped === 't') {
      result += '\t';
    } else if (escaped === 'n') {
      result += '\n';
    } else if (escaped === 'v') {
      result += '\v';
    } else if (escaped === 'f') {
      result += '\f';
    } else if (escaped === 'r') {
      result += '\r';
    } else if (escaped === 'e') {
      result += '\x1b';
    } else if (escaped === '"' || escaped === '\\' || escaped === '/') {
      result += escaped;
    } else if (escaped === 'x') {
      const hex = readHex(text, i + 1, 2);
      if (hex === null) {
        result += 'x';
      } else {
        result += String.fromCodePoint(hex.value);
        i += hex.length;
      }
    } else if (escaped === 'u') {
      const hex = readHex(text, i + 1, 4);
      if (hex === null) {
        result += 'u';
      } else {
        result += String.fromCodePoint(hex.value);
        i += hex.length;
      }
    } else if (escaped === 'U') {
      const hex = readHex(text, i + 1, 8);
      if (hex === null) {
        result += 'U';
      } else {
        result += String.fromCodePoint(hex.value);
        i += hex.length;
      }
    } else {
      result += escaped;
    }
  }
  return result;
}

function readHex(text, start, length) {
  if (start + length > text.length - 1) {
    return null;
  }

  let value = 0;
  for (let i = 0; i < length; i += 1) {
    const ch = text[start + i];
    if (!isHexDigit(ch)) {
      return null;
    }
    value = (value * 16) + hexDigitValue(ch);
  }
  return { value, length };
}

function hexDigitValue(ch) {
  if (ch >= '0' && ch <= '9') {
    return ch.charCodeAt(0) - 48;
  }
  if (ch >= 'a' && ch <= 'f') {
    return ch.charCodeAt(0) - 87;
  }
  return ch.charCodeAt(0) - 55;
}

export function resolvePlainScalar(text) {
  const lowered = text.toLowerCase();
  if (BOOLEAN_VALUES.has(lowered)) {
    return BOOLEAN_VALUES.get(lowered);
  }
  if (NULL_VALUES.has(lowered)) {
    return null;
  }

  const integer = parseInteger(text);
  if (integer !== null) {
    return integer;
  }

  const float = parseFloatScalar(text);
  if (float !== null) {
    return float;
  }

  const timestamp = parseTimestamp(text);
  if (timestamp !== null) {
    return timestamp;
  }

  return text;
}

export function scalarKeyText(value) {
  if (typeof value === 'string') {
    return value;
  }
  return scalarText(value);
}

function parseInteger(text) {
  let index = 0;
  let negative = false;

  if (text[index] === '+' || text[index] === '-') {
    negative = text[index] === '-';
    index += 1;
  }

  if (index >= text.length) {
    return null;
  }

  if (text[index] === '0' && index + 1 < text.length) {
    const prefix = text[index + 1];
    if (prefix === 'x' || prefix === 'X') {
      const digits = text.slice(index + 2);
      if (digits.length === 0 || !allDigitsInBase(digits, 16)) {
        return null;
      }
      return new YamlInteger(formatBigInt(parseDigits(digits, 16), negative));
    }
    if (prefix === 'b' || prefix === 'B') {
      const digits = text.slice(index + 2);
      if (digits.length === 0 || !allDigitsInBase(digits, 2)) {
        return null;
      }
      return new YamlInteger(formatBigInt(parseDigits(digits, 2), negative));
    }

    const rest = text.slice(index + 1);
    if (allDigitsInBase(rest, 8)) {
      return new YamlInteger(formatBigInt(parseDigits(rest, 8), negative));
    }
    return null;
  }

  const digits = text.slice(index);
  if (digits.length === 0 || !allDigitsInBase(digits, 10)) {
    return null;
  }

  return new YamlInteger(formatBigInt(parseDigits(digits, 10), negative));
}

function parseFloatScalar(text) {
  if (text === '.inf' || text === '.Inf' || text === '.INF') {
    return new YamlFloat('.inf');
  }
  if (text === '+.inf' || text === '+.Inf' || text === '+.INF') {
    return new YamlFloat('.inf');
  }
  if (text === '-.inf' || text === '-.Inf' || text === '-.INF') {
    return new YamlFloat('-.inf');
  }
  if (text === '.nan' || text === '.NaN' || text === '.NAN') {
    return new YamlFloat('.nan');
  }

  let index = 0;
  let sign = '';

  if (text[index] === '+' || text[index] === '-') {
    sign = text[index];
    index += 1;
  }

  if (index >= text.length) {
    return null;
  }
  if (sign !== '' && text[index] === '.') {
    return null;
  }

  let whole = '';
  while (index < text.length && isDigit(text[index])) {
    whole += text[index];
    index += 1;
  }

  if (index >= text.length || text[index] !== '.') {
    return null;
  }
  index += 1;

  let fraction = '';
  while (index < text.length && isDigit(text[index])) {
    fraction += text[index];
    index += 1;
  }

  if (index !== text.length) {
    return null;
  }
  if (whole.length === 0 && fraction.length === 0) {
    return null;
  }

  const normalizedWhole = normalizeDecimalDigits(whole);
  const normalizedFraction = normalizeFractionDigits(fraction);
  const negativeZero = sign === '-' && normalizedWhole === '0' && normalizedFraction === '0';
  const prefix = sign === '-' || negativeZero ? sign : '';
  return new YamlFloat(`${prefix}${normalizedWhole}.${normalizedFraction}`);
}

function parseTimestamp(text) {
  if (text.length >= 10 && isDatePart(text, 0)) {
    if (text.length === 10) {
      return new YamlTimestamp(text);
    }

    const separator = text[10];
    if (separator !== 'T' && separator !== 't' && separator !== ' ') {
      return null;
    }

    const time = parseTimePart(text, 11);
    if (time === null) {
      return null;
    }

    return new YamlTimestamp(`${text.slice(0, 10)} ${time}`);
  }
  return null;
}

function parseTimePart(text, index) {
  if (index + 8 > text.length) {
    return null;
  }
  if (!isTwoDigits(text, index) || text[index + 2] !== ':' || !isTwoDigits(text, index + 3) || text[index + 5] !== ':' || !isTwoDigits(text, index + 6)) {
    return null;
  }

  let end = index + 8;
  let fraction = '';
  if (end < text.length && text[end] === '.') {
    end += 1;
    while (end < text.length && isDigit(text[end])) {
      fraction += text[end];
      end += 1;
    }
    if (fraction.length === 0) {
      return null;
    }
  }

  let zone = '';
  if (end < text.length) {
    const zoneChar = text[end];
    if (zoneChar === 'Z' || zoneChar === 'z') {
      zone = '+00:00';
      end += 1;
    } else if (zoneChar === '+' || zoneChar === '-') {
      const sign = zoneChar;
      end += 1;
      if (end + 1 >= text.length || !isTwoDigits(text, end)) {
        return null;
      }
      const hours = text.slice(end, end + 2);
      end += 2;
      let minutes = '00';
      if (end < text.length && text[end] === ':') {
        end += 1;
        if (end + 1 >= text.length || !isTwoDigits(text, end)) {
          return null;
        }
        minutes = text.slice(end, end + 2);
        end += 2;
      } else if (end + 1 < text.length && isTwoDigits(text, end)) {
        minutes = text.slice(end, end + 2);
        end += 2;
      }
      zone = `${sign}${hours}:${minutes}`;
    }
  }

  if (end !== text.length) {
    return null;
  }

  const time = text.slice(index, index + 8);
  return `${time}${fraction.length > 0 ? `.${fraction}` : ''}${zone}`;
}

function isDatePart(text, index) {
  return (
    index + 10 <= text.length &&
    isDigit(text[index]) &&
    isDigit(text[index + 1]) &&
    isDigit(text[index + 2]) &&
    isDigit(text[index + 3]) &&
    text[index + 4] === '-' &&
    isDigit(text[index + 5]) &&
    isDigit(text[index + 6]) &&
    text[index + 7] === '-' &&
    isDigit(text[index + 8]) &&
    isDigit(text[index + 9])
  );
}

function isTwoDigits(text, index) {
  return index + 1 < text.length && isDigit(text[index]) && isDigit(text[index + 1]);
}

function normalizeDecimalDigits(text) {
  let index = 0;
  while (index < text.length && text[index] === '0') {
    index += 1;
  }
  if (index === text.length) {
    return '0';
  }
  return text.slice(index);
}

function normalizeFractionDigits(text) {
  if (text.length === 0) {
    return '0';
  }

  let end = text.length;
  while (end > 0 && text[end - 1] === '0') {
    end -= 1;
  }
  if (end === 0) {
    return '0';
  }
  return text.slice(0, end);
}

function allDigitsInBase(text, base) {
  for (let i = 0; i < text.length; i += 1) {
    const value = digitValue(text[i]);
    if (value < 0 || value >= base) {
      return false;
    }
  }
  return text.length > 0;
}

function digitValue(ch) {
  if (ch >= '0' && ch <= '9') {
    return ch.charCodeAt(0) - 48;
  }
  if (ch >= 'a' && ch <= 'f') {
    return ch.charCodeAt(0) - 87;
  }
  if (ch >= 'A' && ch <= 'F') {
    return ch.charCodeAt(0) - 55;
  }
  return -1;
}

function parseDigits(text, base) {
  let value = 0n;
  const baseBigInt = BigInt(base);
  for (let i = 0; i < text.length; i += 1) {
    value = (value * baseBigInt) + BigInt(digitValue(text[i]));
  }
  return value;
}

function formatBigInt(value, negative) {
  if (value === 0n) {
    return '0';
  }
  return `${negative ? '-' : ''}${value.toString(10)}`;
}

export function shouldQuoteString(text) {
  if (text.length === 0) {
    return true;
  }
  if (text === '---' || text === '...') {
    return true;
  }
  if (resolvesToNonString(text)) {
    return true;
  }
  if (text[0] === ' ' || text[text.length - 1] === ' ') {
    return true;
  }

  const first = text[0];
  if (first === '#' || first === '&' || first === '*' || first === '!' || first === '|' || first === '>' || first === "'" || first === '"' || first === '%' || first === '@' || first === '`') {
    return true;
  }
  if ((first === '-' || first === '?' || first === ':') && (text.length === 1 || text[1] === ' ' || text[1] === '\t')) {
    return true;
  }

  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    if (ch === '\n' || ch === '\r' || ch === '\t') {
      return true;
    }
    if (ch === '[' || ch === ']' || ch === '{' || ch === '}') {
      return true;
    }
    if (ch === ':' && (i + 1 === text.length || text[i + 1] === ' ' || text[i + 1] === '\t')) {
      return true;
    }
    if (ch === '#' && (i === 0 || text[i - 1] === ' ' || text[i - 1] === '\t')) {
      return true;
    }
  }

  return false;
}

function resolvesToNonString(text) {
  const value = resolvePlainScalar(text);
  return value !== text;
}

export function isPlainStyleScalar(value) {
  return typeof value === 'string' && !shouldQuoteString(value) && value.indexOf('\n') === -1;
}

export function escapeSingleQuoted(text) {
  let result = '';
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] === "'") {
      result += "''";
    } else {
      result += text[i];
    }
  }
  return result;
}

export function formatInlineScalar(value, indentBase) {
  if (value === null) {
    return { text: 'null', plain: true };
  }
  if (typeof value === 'boolean') {
    return { text: value ? 'true' : 'false', plain: true };
  }
  if (value instanceof YamlInteger || value instanceof YamlFloat || value instanceof YamlTimestamp) {
    return { text: value.text, plain: true };
  }
  if (typeof value !== 'string') {
    throw new Error('Unsupported inline scalar');
  }

  if (value.indexOf('\n') !== -1) {
    let text = "'";
    const continuation = ' '.repeat(indentBase + 2);
    for (let i = 0; i < value.length; i += 1) {
      const ch = value[i];
      if (ch === "'") {
        text += "''";
      } else if (ch === '\n') {
        text += `\n\n${continuation}`;
      } else {
        text += ch;
      }
    }
    text += "'";
    return { text, plain: false };
  }

  if (shouldQuoteString(value)) {
    return { text: `'${escapeSingleQuoted(value)}'`, plain: false };
  }

  return { text: value, plain: true };
}

export function isScalarValue(value) {
  return value === null || typeof value === 'boolean' || typeof value === 'string' || isScalarWrapper(value);
}

